import 'dart:math';\n\n/// Handles statistical calculations and outlier detection.\nclass StatisticsCalculator {\n  /// Calculates the arithmetic mean of a list of numbers.\n  double calculateMean(List<double> numbers) {\n    if (numbers.isEmpty) return 0.0;\n    final sum = numbers.reduce((a, b) => a + b);\n    return sum / numbers.length;\n  }\n\n  /// Calculates the median of a list of numbers.\n  double calculateMedian(List<double> numbers) {\n    if (numbers.isEmpty) return 0.0;\n    final sorted = List<double>.from(numbers) ..sort();\n    final mid = sorted.length ~/ 2;\n    if (sorted.length % 2 == 0) {\n      return (sorted[mid - 1] + sorted[mid]) / 2.0;\n    } else {\n      return sorted[mid];\n    }\n  }\n\n  /// Calculates the mode(s) of a list of numbers.\n  /// Returns the most frequent value.\n  double calculateMode(List<double> numbers) {\n    if (numbers.isEmpty) return 0.0;\n\n    final frequency = <double, int>{};\n    for (final num in numbers) {\n      frequency[num] = (frequency[num] ?? 0) + 1;\n    }\n\n    int maxCount = 0;\n    double modeValue = 0.0;\n\n    for (final entry in frequency.entries) {\n      if (entry.value > maxCount) {\n        maxCount = entry.value;\n        modeValue = entry.key;\n      }\n    }\n\n    return modeValue;\n  }\n\n  /// Calculates the variance of a list of numbers (population variance).\n  double calculateVariance(List<double> numbers) {\n    if (numbers.isEmpty) return 0.0;\n    final mean = calculateMean(numbers);\n    final sumSquaredDiffs = numbers.map((num) => pow(num - mean, 2)).reduce((a, b) => a + b);\n    return sumSquaredDiffs / numbers.length;\n  }\n\n  /// Calculates the standard deviation of a list of numbers.\n  double calculateStandardDeviation(List<double> numbers) {\n    return sqrt(calculateVariance(numbers));\n  }\n\n  /// Detects outliers using Z-score method.\n  /// Returns a list of [value, z_score] for values with |z_score| > 2.\n  List<List<double>> detectOutliers(List<double> numbers) {\n    if (numbers.length < 3) return [];\n\n    final mean = calculateMean(numbers);\n    final stdDev = calculateStandardDeviation(numbers);\n\n    if (stdDev == 0) return [];\n\n    final outliers = <List<double>>[];\n    for (final num in numbers) {\n      final zScore = (num - mean) / stdDev;\n      if (zScore.abs() > 2.0) {\n        outliers.add([num, zScore]);\n      }\n    }\n\n    return outliers;\n  }\n}\n
